// Evaluate VIP Tier, Language, and Multi-Channel Tone
const incoming = $input.first().json;
const body = incoming.body || incoming;
const correlationId = body.correlationId || `corr_vip_${Date.now()}`;
const lead = body.lead || body.data?.lead || body;

const riisScore = Number(body.riisScore || body.riis?.score || 85);
const diraRisk = body.diraRiskLevel || body.dira?.riskLevel || 'LOW';
const budgetAed = Number(body.budgetAed || lead.budgetAed || 15000000);
const segment = (body.segment || lead.segment || 'PT_HNW').toUpperCase();
const phone = (lead.phone || body.phone || '+971543871702').replace(/[^0-9+]/g, '');
const name = lead.name || body.name || 'Private Sovereign Client';
const email = lead.email || body.email || 'privateadvisory@emanuelrendas.com';
const briefUrl = body.briefUrl || `https://www.emanuelrendas.com/brief/${body.briefId || 'default'}`;

// Select language tone based on segment
let language = 'en';
let salutation = `Dear ${name}`;
let voiceAccent = 'british_executive';

if (segment === 'PT_HNW') {
  language = 'pt';
  salutation = `Estimado(a) ${name}`;
  voiceAccent = 'portuguese_sovereign';
} else if (segment === 'ES_HNW') {
  language = 'es';
  salutation = `Estimado(a) ${name}`;
  voiceAccent = 'spanish_executive';
}

const isVipTier1 = budgetAed >= 5000000 || riisScore >= 80;

return [{
  json: {
    correlationId,
    isVipTier1,
    lead: {
      name,
      email,
      phone,
      segment,
      budgetAed,
      riisScore,
      diraRisk,
      briefUrl,
      language,
      salutation,
      voiceAccent
    },
    timestamp: new Date().toISOString()
  }
}];

// Prepare Multilingual WhatsApp Interactive Payload & Voice Audio Script
const flowData = $input.first().json;
const leadContext = $('2. Evaluate VIP Tier & Persona').first().json.lead;
const correlationId = $('2. Evaluate VIP Tier & Persona').first().json.correlationId;

let waBodyText = '';
let audioVoiceScript = '';

if (leadContext.language === 'pt') {
  waBodyText = `🏛 *RAIOC Private Sovereign Advisory*

${leadContext.salutation},
O seu dossiê institucional para alocação patrimonial em Dubai (AED ${(leadContext.budgetAed/1000000).toFixed(1)}M) está concluído.

• *Classificação RIIS:* ${leadContext.riisScore}/100 [Tier-1]
• *Garantia Fiduciária:* Lei nº 8 de 2007 (Escrow 100% Protegido)
• *Visto Gold 10 Anos:* Qualificado

Consulte o dossiê confidencial:
${leadContext.briefUrl}`;
  audioVoiceScript = `Olá ${leadContext.name}. Aqui é Emanuel Rendas. Estruturámos a sua alocação institucional em Dubai com proteção fiduciária total ao abrigo da Lei número 8. O seu memorando executivo está disponível no link enviado.`;
} else if (leadContext.language === 'es') {
  waBodyText = `🏛 *RAIOC Private Sovereign Advisory*

${leadContext.salutation},
Su dossier institucional para la asignación patrimonial en Dubái (AED ${(leadContext.budgetAed/1000000).toFixed(1)}M) ha sido generado.

• *Puntuación RIIS:* ${leadContext.riisScore}/100 [Tier-1]
• *Protección Fiduciaria:* Ley nº 8 de 2007 (100% Escrow)
• *Golden Visa 10 Años:* Aprobada

Acceda a su informe confidencial:
${leadContext.briefUrl}`;
  audioVoiceScript = `Estimado ${leadContext.name}, le saluda Emanuel Rendas. Hemos completado el análisis de asignación patrimonial en Dubái bajo la Ley número 8 de fideicomiso. Puede revisar su informe en el enlace adjunto.`;
} else {
  waBodyText = `🏛 *RAIOC Private Sovereign Advisory*

${leadContext.salutation},
Your institutional Dubai capital allocation brief (AED ${(leadContext.budgetAed/1000000).toFixed(1)}M) has been compiled.

• *RIIS Readiness:* ${leadContext.riisScore}/100 [Tier-1]
• *Statutory Shield:* Dubai Law No. (8) of 2007 (100% Escrow Banking)
• *Golden Visa 10-Year:* Qualified

Access confidential brief:
${leadContext.briefUrl}`;
  audioVoiceScript = `Good day ${leadContext.name}. This is Emanuel Rendas. Your institutional Dubai prime asset memorandum is compiled with full statutory escrow protection under Dubai Law Number 8. Please review your briefing at the link provided.`;
}

return [{
  json: {
    correlationId,
    lead: leadContext,
    flowTeaser: flowData,
    waBodyText,
    audioVoiceScript,
    directBookingUrl: `https://wa.me/971543871702?text=${encodeURIComponent(`Hello Emanuel — I received the VIP briefing (${leadContext.name}) and would like to schedule a private advisory call.`)}`,
    timestamp: new Date().toISOString()
  }
}];

